`timescale 1ns/1ps

// =============================================================================
// orchestrator — the PNM SoC family as one parameterized module
//
// ROLE selects the class:  0 = CHIP  (PCIe router chip, MoE dispatch)
//                          1 = MCU   (bare-metal RV32I + UART)
//                          2 = SBC   (RV32IMA + DRAM + PCIe + NVMe)
//                          3 = SBC_MOE (SBC + on-die MoE gating SRAM)
// The four legacy module names are thin wrappers around this module.
// Generated by gen_orchestrator.py — edit the source variants, not this.
// =============================================================================
module orchestrator #(
    parameter ROLE           = 0,
    parameter CLK_FREQ       = 100_000_000,
    parameter BAUD_RATE      = 115200,
    parameter NUM_LAYERS     = 8,
    parameter BOARD_X        = 8,
    parameter BOARD_Y        = 8,
    parameter NUM_NODES      = NUM_LAYERS * BOARD_X * BOARD_Y,
    parameter MAX_EXPERTS    = 128,
    parameter TOP_K          = 8,
    parameter HIDDEN_SIZE    = 2816,
    parameter VENDOR_ID      = 16'h4D50,
    parameter DRAM_WORDS     = 1048576,
    parameter DRAM_LATENCY   = 4,
    parameter SRAM_WORDS     = 131072,
    parameter GATING_ENTRIES = 32768,
    parameter ARRAY_SIZE     = 16
)(
    input  wire        clk,
    input  wire        rst_n,
    // UART console (MCU/SBC/SBC_MOE)
    input  wire        uart_rx,
    output wire        uart_tx,
    // PCIe (CHIP/SBC_MOE)
    input  wire [7:0]  pcie_in_data,
    input  wire        pcie_in_valid,
    input  wire        pcie_in_sop,
    input  wire        pcie_in_eop,
    output wire        pcie_in_ready,
    output wire [7:0]  pcie_out_data,
    output wire        pcie_out_valid,
    output wire        pcie_out_sop,
    output wire        pcie_out_eop,
    input  wire        pcie_out_ready,
    // POST discovery sideband
    input  wire [NUM_NODES-1:0] topology_rdy,
    // Spine injection
    output wire [7:0]  spine_inject_data,
    output wire        spine_inject_valid,
    output wire        spine_inject_sop,
    output wire        spine_inject_eop,
    input  wire        spine_inject_ready,
    output wire [1:0]  spine_inject_vc,
    // Spine extraction
    input  wire [7:0]  spine_extract_data,
    input  wire        spine_extract_valid,
    input  wire        spine_extract_sop,
    input  wire        spine_extract_eop,
    input  wire [1:0]  spine_extract_vc,
    // External interrupts (MCU uses [7:0]; SBC/SBC_MOE [15:0])
    input  wire [15:0] ext_irq,
    // Status (CHIP)
    output wire        boot_done,
    output wire [31:0] dispatches,
    output wire [31:0] weight_flits,
    output wire [31:0] errors
);

    localparam ROLE_CHIP    = 0;
    localparam ROLE_MCU     = 1;
    localparam ROLE_SBC     = 2;
    localparam ROLE_SBC_MOE = 3;

    function [15:0] crc16_next;
        input [15:0] crc_in;
        input [7:0]  data_in;
        reg [15:0] crc;
        integer i;
        begin
            crc = crc_in ^ {data_in, 8'h00};
            for (i = 0; i < 8; i = i + 1) begin
                if (crc[15]) crc = (crc << 1) ^ 16'h1021;
                else         crc = crc << 1;
            end
            crc16_next = crc;
        end
    endfunction

    generate
        if (ROLE == ROLE_CHIP) begin : g_chip
            // these were `output reg` ports; now internal
            reg [7:0]  pcie_out_data_r;
            reg        pcie_out_valid_r, pcie_out_sop_r, pcie_out_eop_r;
            reg        boot_done_r;
            reg [31:0] dispatches_r, weight_flits_r, errors_r;
                // =========================================================================
                // Internal constants
                // =========================================================================
                localparam CTRL_WEIGHT_UPLOAD = 8'h82;  // vc_class=2 | OP_COMPUTE | rsvd[1] weight marker (0x80/0x81 are compute/echo; 0xA0/0xB0 are KV ops)
                localparam CTRL_COMPUTE       = 8'h80;  // vc_class=2 | OP_COMPUTE
                localparam CTRL_FORWARD       = 8'h90;  // vc_class=2 | OP_FORWARD
                localparam REQ_MODULE         = 8'hEE;  // AOT-fixed requester (spine root)
                localparam VC_DESCENT         = 2'b10;  // class 2: spine descent
                localparam VC_EGRESS          = 2'b00;  // class 0: board egress
                localparam MAX_PKT_BYTES      = 65535;  // max payload per flit

                // =========================================================================
                // Boot FSM states
                // =========================================================================
                localparam BOOT_RESET     = 3'd0;
                localparam BOOT_POST_PING = 3'd1;
                localparam BOOT_POST_WAIT = 3'd2;
                localparam BOOT_LOAD_RT   = 3'd3;  // load routing tables into repeaters
                localparam BOOT_LOAD_WT   = 3'd4;  // receive weight blobs from host
                localparam BOOT_LOAD_MOE  = 3'd5;  // load MoE gating weights into SRAM
                localparam BOOT_READY     = 3'd6;

                reg [2:0]  boot_state;
                reg [7:0]  boot_phase;     // sub-step counter within each boot phase
                reg [15:0] post_ping_resp; // count of TOPOLOGY_RDY responses received

                // =========================================================================
                // Routing table: per-node bitmap (11 bits each)
                // Stored in SRAM, indexed by (layer * BOARD_X * BOARD_Y + x * BOARD_Y + y)
                // =========================================================================
                reg [10:0] route_table [0:NUM_NODES-1];

                // =========================================================================
                // MoE expert map: expert_index → (physical_layer, module_id)
                // Stored in SRAM, indexed by (model_layer * MAX_EXPERTS + expert_idx)
                // =========================================================================
                reg [7:0]  moe_layer  [0:NUM_LAYERS*MAX_EXPERTS-1];
                reg [7:0]  moe_module [0:NUM_LAYERS*MAX_EXPERTS-1];

                // =========================================================================
                // Forward declarations (Verilog-2005: must declare before use)
                // =========================================================================
                localparam ADDR_BITS = 20;  // must hold NUM_EXPERTS*HIDDEN_DIM (e.g. 128*2816=360448 for Gemma-4)

                reg [3:0]  pie_pos;
                reg [7:0]  pie_buf [0:5];
                reg [7:0]  fb_layer;
                reg        gate_start;  // pulse to start MoE gating computation

                // =========================================================================
                // MoE gating unit: systolic-array gated matrix-vector multiply + top-K
                // =========================================================================
                wire        gate_done;
                wire [TOP_K*8-1:0]  gate_expert_idx_packed;
                wire [TOP_K*16-1:0] gate_expert_logit_packed;
                wire [TOP_K*8-1:0]  gate_expert_layer_packed;
                wire [TOP_K*8-1:0]  gate_expert_module_packed;
                wire [ADDR_BITS-1:0] gate_hidden_addr;
                wire        gate_fma_busy;
                reg  [15:0] gate_hidden_data;
                reg         gate_hidden_valid;   // pulse: fresh hidden word on gate_hidden_data
                // MoE gating weight upload (PIE_MOE_W): BF16 word stream
                reg [7:0]  mw_hi;
                reg        mw_odd;
                reg [15:0] mw_dim;
                reg [19:0] gate_weight_addr;
                reg [15:0] gate_weight_data;
                reg        gate_weight_load;
                // Hidden-state feed from the token payload (16-bit BF16 words)
                reg [7:0]  gh_hi;
                reg        gh_odd;

                // Latched gating results for dispatch (stable after gate_done)
                reg  [7:0]  dispatch_layer;
                reg  [7:0]  dispatch_module;

                moe_gating #(
                    .NUM_EXPERTS(MAX_EXPERTS),
                    .HIDDEN_DIM(HIDDEN_SIZE),
                    .TOP_K(TOP_K),
                    .ADDR_BITS(ADDR_BITS)
                ) u_gating (
                    .clk           (clk),
                    .rst_n         (rst_n),
                    .start         (gate_start),
                    .done          (gate_done),
                    .current_layer (fb_layer),
                    .hidden_addr   (gate_hidden_addr),
                    .hidden_data   (gate_hidden_data),
                    .hidden_valid  (gate_hidden_valid),
                    .weight_load   (gate_weight_load),
                    .weight_addr   (gate_weight_addr),
                    .weight_data   (gate_weight_data),
                    .moe_layer_in  (moe_layer[pie_buf[0] * MAX_EXPERTS + pie_buf[1]]),
                    .moe_module_in (moe_module[pie_buf[0] * MAX_EXPERTS + pie_buf[1]]),
                    .expert_idx_packed   (gate_expert_idx_packed),
                    .expert_logit_packed (gate_expert_logit_packed),
                    .expert_layer_packed (gate_expert_layer_packed),
                    .expert_module_packed(gate_expert_module_packed),
                    .fma_busy      (gate_fma_busy)
                );

                // =========================================================================
                // POST discovery counter
                // =========================================================================
                reg [15:0] node_count;  // total nodes discovered

                // =========================================================================
                // Flit builder state machine
                // =========================================================================
                localparam FB_IDLE    = 3'd0;
                localparam FB_HDR     = 3'd1;  // accept LAYER_ID, MODULE_ID, CTRL, LEN
                localparam FB_PAYLOAD = 3'd2;  // accept payload bytes
                localparam FB_CRC     = 3'd3;  // compute and append CRC

                reg [2:0]  fb_state;
                reg [7:0]  fb_module;
                reg [7:0]  fb_ctrl;
                reg [15:0] fb_len;
                reg [15:0] fb_pos;      // byte position within payload (flit builder only)
                reg [15:0] fb_crc;      // running CRC-16/CCITT
                reg        fb_active;   // flit builder is processing a message

                reg [15:0] pie_fwd_cnt; // payload bytes forwarded to flit builder

                // =========================================================================
                // PCIe ingress parser state machine
                // =========================================================================
                localparam PIE_IDLE      = 4'd0;
                localparam PIE_CMD       = 4'd1;  // command byte
                localparam PIE_WEIGHT_H  = 4'd2;  // weight upload header
                localparam PIE_WEIGHT_P  = 4'd3;  // weight upload payload
                localparam PIE_RT_NODE   = 4'd4;  // routing table entry
                localparam PIE_MOE_H     = 4'd5;  // MoE map entry
                localparam PIE_INF_TOKEN = 4'd6;  // inference token header
                localparam PIE_INF_TOKEN_P = 4'd7; // inference token payload
                localparam PIE_MOE_W     = 4'd8;  // MoE gating weight header
                localparam PIE_MOE_WP    = 4'd9;  // MoE gating weight payload

                reg [3:0]  pie_state;

                reg [7:0]  pie_cmd;
                reg [15:0] pie_len;

                // =========================================================================
                // Result collection: accumulates tail_up bytes into PCIe egress flits
                // =========================================================================
                localparam RC_IDLE = 2'd0;
                localparam RC_SEND = 2'd1;

                reg [1:0]  rc_state;
                reg [7:0]  rc_buf [0:9]; // result bytes FIFO (head at rc_fifo_head)
                reg        rc_sop [0:9];
                reg        rc_eop [0:9];
                reg [3:0]  rc_pos;
                reg [3:0]  rc_len;
                reg [3:0]  rc_fifo_head;
                reg [3:0]  rc_fifo_cnt;

                // =========================================================================
                // CRC-16 computation (inline, matches crc16.v / crc.go)
                // =========================================================================

                // =========================================================================
                // Flit builder: accepts raw bytes from the PCIe parser and constructs
                // wormhole flits for spine injection
                // =========================================================================

                // Flit builder output registers
                reg [7:0]  fb_out_data;
                reg        fb_out_valid;
                reg        fb_out_sop;
                reg        fb_out_eop;
                wire       fb_out_ready = spine_inject_ready;

                assign spine_inject_data  = fb_out_data;
                assign spine_inject_valid = fb_out_valid;
                assign spine_inject_sop   = fb_out_sop;
                assign spine_inject_eop   = fb_out_eop;
                assign spine_inject_vc    = VC_DESCENT;

                // Flit builder input ready (accepts from PCIe parser)
                reg        fb_in_ready_r;
                wire       fb_in_ready = fb_in_ready_r;

                assign pcie_in_ready = (pie_state == PIE_WEIGHT_P || pie_state == PIE_INF_TOKEN_P) ? (fb_in_ready && fb_state == 3'd2 && (fb_out_ready || !fb_out_valid)) : 1'b1;

                // =========================================================================
                // Main control FSM
                // =========================================================================

                // Boot completion
                wire [15:0] total_nodes = NUM_LAYERS[15:0] * BOARD_X[15:0] * BOARD_Y[15:0];

                always @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin
                        boot_state    <= BOOT_RESET;
                        boot_phase    <= 0;
                        post_ping_resp <= 0;
                        node_count    <= 0;
                        boot_done_r     <= 0;
                        gate_start    <= 0;
                        dispatches_r    <= 0;
                        weight_flits_r  <= 0;
                        errors_r        <= 0;
                        dispatch_layer  <= 1;
                        dispatch_module <= 0;

                        fb_state      <= FB_IDLE;
                        fb_layer      <= 0;
                        fb_module     <= 0;
                        fb_ctrl       <= 0;
                        fb_len        <= 0;
                        fb_pos        <= 0;
                        fb_crc        <= 16'hFFFF;
                        fb_active     <= 0;
                        fb_out_data   <= 0;
                        fb_out_valid  <= 0;
                        fb_out_sop    <= 0;
                        fb_out_eop    <= 0;
                        fb_in_ready_r <= 0;

                        pie_state     <= PIE_IDLE;
                        pie_cmd       <= 0;
                        pie_pos       <= 0;
                        pie_len       <= 0;
                        pie_fwd_cnt   <= 0;

                        rc_state      <= RC_IDLE;
                        rc_pos        <= 0;
                        rc_len        <= 0;
                        rc_fifo_head  <= 0;
                        rc_fifo_cnt   <= 0;
                        gate_hidden_valid <= 0;
                        gate_weight_load  <= 0;
                        mw_odd <= 0; mw_dim <= 0; gh_odd <= 0;
                    end else begin
                        // Defaults
                        fb_out_valid <= 1'b0;
                        fb_out_sop   <= 1'b0;
                        fb_out_eop   <= 1'b0;
                        gate_start   <= 1'b0;
                        gate_hidden_valid <= 1'b0;
                        gate_weight_load  <= 1'b0;

                        // =================================================================
                        // Latch MoE gating results when done
                        // =================================================================
                        if (gate_done) begin
                            dispatch_layer  <= gate_expert_layer_packed[7:0];
                            dispatch_module <= gate_expert_module_packed[7:0];
                        end

                        // =================================================================
                        // Boot FSM
                        // =================================================================
                        case (boot_state)
                            BOOT_RESET: begin
                                boot_phase <= 0;
                                boot_state <= BOOT_POST_PING;
                            end

                            BOOT_POST_PING: begin
                                // Count TOPOLOGY_RDY responses
                                post_ping_resp <= 0;
                                node_count     <= 0;
                                boot_state     <= BOOT_POST_WAIT;
                                boot_phase     <= 0;
                            end

                            BOOT_POST_WAIT: begin
                                // Latch topology_rdy bits over 256 cycles for metastability
                                if (boot_phase < 255)
                                    boot_phase <= boot_phase + 1;
                                else begin
                                    // Count set bits (popcount) — use blocking accumulation
                                    begin : popcount
                                        integer i;
                                        reg [15:0] cnt;
                                        cnt = 0;
                                        for (i = 0; i < NUM_NODES; i = i + 1) begin
                                            if (topology_rdy[i])
                                                cnt = cnt + 1;
                                        end
                                        node_count <= cnt;
                                    end
                                    boot_state <= BOOT_LOAD_RT;
                                    boot_phase <= 0;
                                end
                            end

                            BOOT_LOAD_RT: begin
                                // Routing tables loaded by host driver via PCIe commands
                                if (pie_state == PIE_IDLE && pie_cmd == 8'hFF) begin
                                    pie_cmd <= 0;  // clear to prevent multi-phase skip
                                    boot_state <= BOOT_LOAD_WT;
                                    boot_phase <= 0;
                                end
                            end

                            BOOT_LOAD_WT: begin
                                // Weight blobs loaded by host driver via PCIe commands.
                                if (pie_state == PIE_IDLE && pie_cmd == 8'hFF) begin
                                    pie_cmd <= 0;
                                    boot_state <= BOOT_LOAD_MOE;
                                    boot_phase <= 0;
                                end
                            end

                            BOOT_LOAD_MOE: begin
                                // MoE gating weights + expert map loaded by host.
                                if (pie_state == PIE_IDLE && pie_cmd == 8'hFF) begin
                                    pie_cmd <= 0;
                                    boot_state  <= BOOT_READY;
                                    boot_done_r   <= 1'b1;
                                end
                            end

                            BOOT_READY: begin
                                // Normal operation: dispatch tokens, collect results.
                            end

                            default: boot_state <= BOOT_RESET;
                        endcase

                        // =================================================================
                        // PCIe ingress parser
                        // =================================================================
                        if (pcie_in_valid && pcie_in_ready) begin
                            case (pie_state)
                                PIE_IDLE: begin
                                    pie_cmd <= pcie_in_data;
                                    case (pcie_in_data)
                                        8'h01: pie_state <= PIE_WEIGHT_H;  // weight upload
                                        8'h02: pie_state <= PIE_RT_NODE;   // routing table
                                        8'h03: pie_state <= PIE_MOE_H;     // MoE map
                                        8'h04: pie_state <= PIE_INF_TOKEN; // inference token
                                        8'h05: pie_state <= PIE_MOE_W;     // MoE gating weight
                                        8'hFF: ; // boot phase advance (no-op, handled above)
                                        default: errors_r <= errors_r + 1;
                                    endcase
                                    pie_pos <= 0;
                                end

                                PIE_WEIGHT_H: begin
                                    // Collect: layer(1) + module(1) + len_hi(1) + len_lo(1)
                                    pie_buf[pie_pos[2:0]] <= pcie_in_data;
                                    if (pie_pos == 3) begin
                                        fb_layer  <= pie_buf[0];
                                        fb_module <= pie_buf[1];
                                        fb_len    <= {pie_buf[2], pcie_in_data};
                                        fb_ctrl   <= CTRL_WEIGHT_UPLOAD;
                                        fb_state  <= FB_HDR;
                                        fb_pos    <= 0;
                                        fb_crc    <= 16'hFFFF;
                                        fb_active <= 1;
                                        pie_state <= PIE_WEIGHT_P;
                                        pie_fwd_cnt <= 0;
                                        fb_in_ready_r <= 1;
                                    end else
                                        pie_pos <= pie_pos + 1;
                                end

                                PIE_WEIGHT_P: begin
                                    // Wait for flit builder to finish emitting the flit
                                    // (FB_CRC = 3'd3, then back to FB_IDLE = 3'd0)
                                    if (fb_state == 3'd0 && !fb_active) begin
                                        pie_state <= PIE_IDLE;
                                        fb_in_ready_r <= 0;
                                    end
                                end

                                PIE_RT_NODE: begin
                                    // Collect: node_id(1) + bitmap_hi(1) + bitmap_lo(1)
                                    pie_buf[pie_pos[2:0]] <= pcie_in_data;
                                    if (pie_pos == 2) begin
                                        begin : rt_load
                                            integer idx;
                                            idx = pie_buf[0];  // node_id
                                            if (idx < NUM_NODES)
                                                route_table[idx] <= {pie_buf[1], pcie_in_data};
                                        end
                                        pie_state <= PIE_IDLE;
                                    end else
                                        pie_pos <= pie_pos + 1;
                                end

                                PIE_MOE_H: begin
                                    // Collect: layer(1) + expert(1) + target_layer(1) + target_module(1)
                                    pie_buf[pie_pos[2:0]] <= pcie_in_data;
                                    if (pie_pos == 3) begin
                                        begin : moe_load
                                            integer idx;
                                            idx = pie_buf[0] * MAX_EXPERTS + pie_buf[1];
                                            if (idx < NUM_LAYERS * MAX_EXPERTS) begin
                                                moe_layer[idx]  <= pie_buf[2];
                                                moe_module[idx] <= pcie_in_data;
                                            end
                                        end
                                        pie_state <= PIE_IDLE;
                                    end else
                                        pie_pos <= pie_pos + 1;
                                end

                                PIE_MOE_W: begin
                                    // Collect: layer(1) + expert(1) + rsvd(1); then
                                    // HIDDEN_SIZE BF16 words stream (2 bytes each) into the
                                    // gating unit's weight SRAM.  pie_buf[0]/[1] stay
                                    // latched as layer/expert so the moe_layer_in/
                                    // moe_module_in port presents the expert's coordinates
                                    // at every weight_load pulse.
                                    pie_buf[pie_pos[2:0]] <= pcie_in_data;
                                    if (pie_pos == 2) begin
                                        pie_state <= PIE_MOE_WP;
                                        pie_pos   <= 0;
                                        mw_dim    <= 0;
                                        mw_odd    <= 0;
                                    end else
                                        pie_pos <= pie_pos + 1;
                                end

                                PIE_MOE_WP: begin
                                    // Stream weight words: {2nd byte, 1st byte} per word.
                                    if (!mw_odd) begin
                                        mw_hi  <= pcie_in_data;
                                        mw_odd <= 1;
                                    end else begin
                                        gate_weight_data <= {mw_hi, pcie_in_data};
                                        gate_weight_addr <= pie_buf[1] * HIDDEN_SIZE + mw_dim;
                                        gate_weight_load <= 1'b1;
                                        mw_odd <= 0;
                                        if (mw_dim == HIDDEN_SIZE - 1) begin
                                            pie_state <= PIE_IDLE;
                                            pie_pos   <= 0;
                                        end else
                                            mw_dim <= mw_dim + 1;
                                    end
                                end

                                PIE_INF_TOKEN: begin
                                    // Inference: collect len_hi(1) + len_lo(1), then payload
                                    pie_buf[pie_pos[2:0]] <= pcie_in_data;
                                    if (pie_pos == 0) begin
                                        // First byte after CMD is LEN_HI
                                        pie_pos <= 1;
                                    end else if (pie_pos == 1) begin
                                        // Second byte is LEN_LO — use MoE gating results
                                        fb_layer  <= dispatch_layer;
                                        fb_module <= dispatch_module;
                                        fb_ctrl   <= CTRL_COMPUTE;
                                        fb_len    <= {pie_buf[0], pcie_in_data};
                                        fb_state  <= FB_HDR;
                                        fb_pos    <= 0;
                                        fb_crc    <= 16'hFFFF;
                                        fb_active <= 1;
                                        pie_state <= PIE_INF_TOKEN_P;
                                        pie_fwd_cnt <= 0;
                                        fb_in_ready_r <= 1;
                                        gate_start    <= 1'b1;  // trigger MoE gating computation
                                        dispatches_r <= dispatches_r + 1;
                                    end
                                end

                                PIE_INF_TOKEN_P: begin
                                    // Wait for flit builder to finish emitting the flit
                                    if (fb_state == 3'd0 && !fb_active) begin
                                        pie_state <= PIE_IDLE;
                                        fb_in_ready_r <= 0;
                                    end
                                end
                                default: pie_state <= PIE_IDLE;
                            endcase
                        end

                        // =================================================================
                        // Flit-builder-done check (runs even when pcie_in_valid is deasserted)
                        // =================================================================
                        if ((pie_state == PIE_WEIGHT_P || pie_state == PIE_INF_TOKEN_P)
                            && fb_state == 3'd0 && !fb_active) begin
                            pie_state <= PIE_IDLE;
                            fb_in_ready_r <= 0;
                        end

                        // =================================================================
                        // Flit builder: constructs wormhole flits for spine injection
                        // =================================================================
                        case (fb_state)
                            FB_IDLE: begin
                                fb_out_valid <= 1'b0;
                            end

                            FB_HDR: begin
                                if (fb_out_ready || !fb_out_valid) begin
                                    // Emit: LAYER_ID | MODULE_ID | CTRL | LEN_LO | LEN_HI
                                    // Every header byte must assert valid (a valid&&ready
                                    // sink otherwise skips MODULE/CTRL/LEN entirely).
                                    case (fb_pos)
                                        0: begin fb_out_data <= fb_layer;  fb_out_sop <= 1; fb_out_valid <= 1; end
                                        1: begin fb_out_data <= fb_module; fb_out_sop <= 0; fb_out_valid <= 1; end
                                        2: begin fb_out_data <= fb_ctrl;   fb_out_sop <= 0; fb_out_valid <= 1; end
                                        3: begin fb_out_data <= fb_len[7:0];  fb_out_sop <= 0; fb_out_valid <= 1; end  // LEN_LO
                                        4: begin fb_out_data <= fb_len[15:8]; fb_out_sop <= 0; fb_out_valid <= 1; end  // LEN_HI
                                    endcase
                                    // Update CRC over header bytes (CRC covers MODULE_ID, CTRL, LEN, payload)
                                    if (fb_pos >= 1 && fb_pos <= 4) begin
                                        if (fb_pos == 1)
                                            fb_crc <= crc16_next(16'hFFFF, fb_module);
                                        else if (fb_pos == 2)
                                            fb_crc <= crc16_next(fb_crc, fb_ctrl);
                                        else if (fb_pos == 3)
                                            fb_crc <= crc16_next(fb_crc, fb_len[7:0]);   // LEN_LO
                                        else if (fb_pos == 4)
                                            fb_crc <= crc16_next(fb_crc, fb_len[15:8]);  // LEN_HI
                                    end
                                    if (fb_pos == 4) begin
                                        if (fb_len == 0) begin
                                            fb_state <= FB_CRC;
                                            fb_pos   <= 0;
                                        end else begin
                                            fb_state <= FB_PAYLOAD;
                                            fb_pos   <= 0;
                                        end
                                    end else
                                        fb_pos <= fb_pos + 1;
                                end
                            end

                            FB_PAYLOAD: begin
                                // Forward payload bytes from PCIe parser, respecting backpressure.
                                // During inference, the payload doubles as the gating unit's
                                // hidden-state vector: every pair of forwarded bytes is
                                // presented to moe_gating as one BF16 word (paced by
                                // gate_hidden_valid, consumed by G_LOAD_HIDDEN).
                                if (fb_out_ready || !fb_out_valid) begin
                                    if (fb_in_ready && pcie_in_valid) begin
                                        fb_out_data  <= pcie_in_data;
                                        fb_out_valid <= 1;
                                        fb_out_sop   <= 0;
                                        fb_crc       <= crc16_next(fb_crc, pcie_in_data);
                                        if (pie_state == PIE_INF_TOKEN_P) begin
                                            if (!gh_odd) begin
                                                gh_hi  <= pcie_in_data;
                                                gh_odd <= 1;
                                            end else begin
                                                gate_hidden_data  <= {gh_hi, pcie_in_data};
                                                gate_hidden_valid <= 1'b1;
                                                gh_odd <= 0;
                                            end
                                        end
                                        if (fb_pos == fb_len - 1) begin
                                            fb_state <= FB_CRC;
                                            fb_pos   <= 0;
                                        end else
                                            fb_pos <= fb_pos + 1;
                                    end
                                end
                            end

                            FB_CRC: begin
                                if (fb_out_ready || !fb_out_valid) begin
                                    fb_out_valid <= 1;
                                    fb_out_sop   <= 0;
                                    if (fb_pos == 0) begin
                                        fb_out_data <= fb_crc[15:8]; // CRC_HI
                                        fb_out_eop  <= 0;
                                        fb_pos      <= 1;
                                    end else begin
                                        fb_out_data <= fb_crc[7:0];  // CRC_LO
                                        fb_out_eop  <= 1;
                                        fb_state    <= FB_IDLE;
                                        fb_active   <= 0;
                                        weight_flits_r <= weight_flits_r + 1;
                                    end
                                end
                            end

                            default: fb_state <= FB_IDLE;
                        endcase

                        // =================================================================
                        // Result collection: tail_up → PCIe egress (10-byte FIFO)
                        // Forwards result echoes from the spine back to the host via PCIe.
                        // Incoming bytes are buffered so a host backpressure window never
                        // drops a byte; only a full FIFO counts an error.
                        // =================================================================
                        begin : rc_fifo
                            reg [3:0] rc_widx;
                            reg       rc_can_write;
                            reg       rc_do_drain;
                            rc_widx      = (rc_fifo_head + rc_fifo_cnt) % 4'd10;
                            rc_can_write = spine_extract_valid && boot_done_r && (rc_fifo_cnt != 4'd10);
                            rc_do_drain  = (rc_fifo_cnt != 4'd0) && pcie_out_ready;
                            if (spine_extract_valid && boot_done_r) begin
                                if (rc_fifo_cnt == 4'd10) begin
                                    errors_r <= errors_r + 1;  // FIFO full: byte dropped
                                end else begin
                                    rc_buf[rc_widx] <= spine_extract_data;
                                    rc_sop[rc_widx]  <= spine_extract_sop;
                                    rc_eop[rc_widx]  <= spine_extract_eop;
                                end
                            end
                            if (rc_fifo_cnt != 4'd0) begin
                                if (pcie_out_ready) begin
                                    pcie_out_data_r  <= rc_buf[rc_fifo_head];
                                    pcie_out_sop_r   <= rc_sop[rc_fifo_head];
                                    pcie_out_eop_r   <= rc_eop[rc_fifo_head];
                                    pcie_out_valid_r <= 1;
                                    rc_fifo_head   <= (rc_fifo_head + 1) % 4'd10;
                                end else begin
                                    // Host backpressured: keep presenting the head byte.
                                    pcie_out_valid_r <= 1;
                                end
                            end else begin
                                pcie_out_valid_r <= 0;
                            end
                            // Net the occupancy update so a simultaneous spine write and
                            // PCIe drain in one cycle advance the count by zero (+1 write,
                            // -1 drain) instead of letting the last NBA assignment drop one
                            // of the two events.
                            if (rc_can_write && rc_do_drain)
                                rc_fifo_cnt <= rc_fifo_cnt;
                            else if (rc_can_write)
                                rc_fifo_cnt <= rc_fifo_cnt + 1;
                            else if (rc_do_drain)
                                rc_fifo_cnt <= rc_fifo_cnt - 1;
                        end

                        // =================================================================
                        // Reset on boot_phase commands
                        // =================================================================
                        if (pcie_in_valid && pcie_in_data == 8'hFF && pie_state == PIE_IDLE) begin
                            pie_cmd <= 8'hFF; // signal boot phase advance
                        end
                    end
                end
            assign boot_done    = boot_done_r;
            assign dispatches   = dispatches_r;
            assign weight_flits = weight_flits_r;
            assign errors       = errors_r;
            assign pcie_out_data  = pcie_out_data_r;
            assign pcie_out_valid = pcie_out_valid_r;
            assign pcie_out_sop   = pcie_out_sop_r;
            assign pcie_out_eop   = pcie_out_eop_r;
        end

        if (ROLE == ROLE_MCU) begin : g_mcu
                // =========================================================================
                // Bus interconnect
                // =========================================================================
                wire [31:0] cpu_addr;
                wire [31:0] cpu_wdata;
                wire [31:0] cpu_rdata;
                wire        cpu_we;
                wire [3:0]  cpu_be;
                wire        cpu_valid;
                wire        cpu_ready;
                wire        cpu_error;

                reg  [31:0] rom_rdata;
                reg  [31:0] sram_rdata;
                wire [31:0] uart_rdata;
                reg  [31:0] pnm_rdata;
                wire [31:0] cpu_fetch_addr;

                wire sel_rom  = (cpu_fetch_addr[31:13] == 19'h0000);   // 0x0000_0000, 8KB
                wire sel_uart = (cpu_addr[31:8]  == 24'h1000_00);      // 0x1000_0000
                wire sel_sram = (cpu_addr[31:12] == 20'h8000_0);       // 0x8000_0000, 4KB
                wire sel_pnm  = (cpu_addr[31:8]  == 24'hF000_00);      // 0xF000_0000

                assign cpu_error = 1'b0;

                reg [31:0] mux_rdata;
                always @(*) begin
                    mux_rdata = 32'h0;
                    if (sel_rom)       mux_rdata = rom_rdata;
                    else if (sel_uart) mux_rdata = uart_rdata;
                    else if (sel_sram) mux_rdata = sram_rdata;
                    else if (sel_pnm)  mux_rdata = pnm_rdata;
                end

                assign cpu_rdata = mux_rdata;
                // every access is acknowledged (an unmapped read returns zero,
                // an unmapped write is dropped) — see bmc_orchestrator_top.v
                assign cpu_ready = 1'b1;

                wire [7:0] cpu_irq;

                // =========================================================================
                // CPU core (RV32I subset — no M, no CSR beyond machine-mode minimums)
                // =========================================================================
                rv32_core #(
                    .RESET_ADDR(32'h0000_0000),
                    .NMINT(8)
                ) u_cpu (
                    .clk       (clk),
                    .rst_n     (rst_n),
                    .bus_addr  (cpu_addr),
                    .bus_wdata (cpu_wdata),
                    .bus_rdata (cpu_rdata),
                    .bus_we    (cpu_we),
                    .bus_be    (cpu_be),
                    .bus_valid (cpu_valid),
                    .bus_ready (cpu_ready),
                    .bus_error (cpu_error),
                    .irq       (cpu_irq),
                    .fetch_addr(cpu_fetch_addr)
                );

                // =========================================================================
                // Boot ROM (8KB — route tables + dispatch loop)
                // =========================================================================
                reg [31:0] rom [0:2047];
                always @(*) rom_rdata = rom[cpu_fetch_addr[12:2]];

                // =========================================================================
                // SRAM (4KB — stack + doorbell scratch)
                // =========================================================================
                reg [31:0] sram [0:1023];
                always @(*) begin
                    if (sel_sram) sram_rdata = sram[cpu_addr[11:2]];
                    else          sram_rdata = 32'h0;
                end

                always @(posedge clk) begin
                    if (sel_sram && cpu_valid && cpu_we) begin
                        if (cpu_be[0]) sram[cpu_addr[11:2]][7:0]   <= cpu_wdata[7:0];
                        if (cpu_be[1]) sram[cpu_addr[11:2]][15:8]  <= cpu_wdata[15:8];
                        if (cpu_be[2]) sram[cpu_addr[11:2]][23:16] <= cpu_wdata[23:16];
                        if (cpu_be[3]) sram[cpu_addr[11:2]][31:24] <= cpu_wdata[31:24];
                    end
                end

                // =========================================================================
                // UART
                // =========================================================================
                wire        uart_irq;
                wire        uart_ready;
                uart #(
                    .CLK_FREQ(CLK_FREQ),
                    .BAUD_RATE(BAUD_RATE)
                ) u_uart (
                    .clk      (clk),
                    .rst_n    (rst_n),
                    .addr     (cpu_addr),
                    .wdata    (cpu_wdata),
                    .rdata    (uart_rdata),
                    .we       (cpu_we),
                    .valid    (sel_uart && cpu_valid),
                    .ready    (uart_ready),
                    .uart_rx  (uart_rx),
                    .uart_tx  (uart_tx),
                    .irq      (uart_irq)
                );

                // IRQ wiring: irq[0]=UART, irq[1]=doorbell, rest external
                assign cpu_irq[0] = uart_irq;
                assign cpu_irq[1] = spine_extract_valid;
                assign cpu_irq[7:2] = ext_irq[7:2];

                // =========================================================================
                // PNM Router Engine (flit builder, same wire format)
                // =========================================================================
                localparam CTRL_COMPUTE = 8'h80;
                localparam VC_DESCENT   = 2'b10;

                reg [7:0]  route_layer;
                reg [7:0]  route_module;
                reg [15:0] route_len;
                reg [7:0]  route_payload [0:255];
                reg [7:0]  route_wpos;
                reg [31:0] route_errors;
                reg [31:0] route_dispatches;
                reg        boot_done_r;
                assign boot_done = boot_done_r;

                localparam FB_IDLE    = 3'd0;
                localparam FB_HDR     = 3'd1;
                localparam FB_PAYLOAD = 3'd2;
                localparam FB_CRC     = 3'd3;

                reg [2:0]  fb_state;
                reg [7:0]  fb_layer_r;
                reg [7:0]  fb_module_r;
                reg [7:0]  fb_ctrl;
                reg [15:0] fb_len;
                reg [15:0] fb_pos;
                reg [15:0] fb_crc;
                reg        fb_active;
                reg [7:0]  fb_out_data_r;
                reg        fb_out_valid_r;
                reg        fb_out_sop_r;
                reg        fb_out_eop_r;

                wire fb_out_ready = spine_inject_ready;
                wire pnm_busy = fb_active;

                assign spine_inject_data  = fb_out_data_r;
                assign spine_inject_valid = fb_out_valid_r;
                assign spine_inject_sop   = fb_out_sop_r;
                assign spine_inject_eop   = fb_out_eop_r;
                assign spine_inject_vc    = VC_DESCENT;

                wire [7:0] pnm_addr = cpu_addr[7:0];

                always @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin
                        route_layer      <= 8'h0;
                        route_module     <= 8'h0;
                        route_len        <= 16'h0;
                        route_wpos       <= 8'h0;
                        route_errors     <= 32'h0;
                        route_dispatches <= 32'h0;
                        fb_state         <= FB_IDLE;
                        fb_layer_r       <= 8'h0;
                        fb_module_r      <= 8'h0;
                        fb_ctrl          <= 8'h0;
                        fb_len           <= 16'h0;
                        fb_pos           <= 16'h0;
                        fb_crc           <= 16'hFFFF;
                        fb_active        <= 1'b0;
                        fb_out_data_r    <= 8'h0;
                        fb_out_valid_r   <= 1'b0;
                        fb_out_sop_r     <= 1'b0;
                        fb_out_eop_r     <= 1'b0;
                        pnm_rdata        <= 32'h0;
                        boot_done_r      <= 1'b0;
                    end else begin
                        fb_out_valid_r <= 1'b0;
                        fb_out_sop_r   <= 1'b0;
                        fb_out_eop_r   <= 1'b0;

                        if (sel_pnm && cpu_valid && cpu_we) begin
                            case (pnm_addr)
                                8'h04: route_layer  <= cpu_wdata[7:0];
                                8'h08: route_module <= cpu_wdata[7:0];
                                8'h0C: route_len    <= cpu_wdata[15:0];
                                8'h10: begin
                                    route_payload[route_wpos] <= cpu_wdata[7:0];
                                    route_wpos <= route_wpos + 1;
                                end
                                8'h00: begin
                                    if (cpu_wdata[2]) boot_done_r <= 1'b1;
                                    if (!pnm_busy && cpu_wdata[0]) begin
                                        fb_layer_r  <= route_layer;
                                        fb_module_r <= route_module;
                                        fb_ctrl     <= CTRL_COMPUTE;
                                        fb_len      <= route_len;
                                        fb_state    <= FB_HDR;
                                        fb_pos      <= 16'h0;
                                        fb_crc      <= 16'hFFFF;
                                        fb_active   <= 1'b1;
                                        route_wpos  <= 8'h0;
                                    end
                                end
                                default: ;
                            endcase
                        end

                        case (fb_state)
                            FB_IDLE: ;

                            FB_HDR: begin
                                if (fb_out_ready || !fb_out_valid_r) begin
                                    fb_out_valid_r <= 1;
                                    case (fb_pos)
                                        0: begin fb_out_data_r <= fb_layer_r;  fb_out_sop_r <= 1; end
                                        1: begin fb_out_data_r <= fb_module_r; end
                                        2: begin fb_out_data_r <= fb_ctrl;     end
                                        3: begin fb_out_data_r <= fb_len[7:0]; end
                                        4: begin fb_out_data_r <= fb_len[15:8];end
                                    endcase
                                    if (fb_pos >= 1 && fb_pos <= 4) begin
                                        if (fb_pos == 1)      fb_crc <= crc16_next(16'hFFFF, fb_module_r);
                                        else if (fb_pos == 2) fb_crc <= crc16_next(fb_crc, fb_ctrl);
                                        else if (fb_pos == 3) fb_crc <= crc16_next(fb_crc, fb_len[7:0]);
                                        else                  fb_crc <= crc16_next(fb_crc, fb_len[15:8]);
                                    end
                                    if (fb_pos == 4) begin
                                        fb_state <= (fb_len == 0) ? FB_CRC : FB_PAYLOAD;
                                        fb_pos   <= 0;
                                    end else
                                        fb_pos <= fb_pos + 1;
                                end
                            end

                            FB_PAYLOAD: begin
                                if (fb_out_ready || !fb_out_valid_r) begin
                                    fb_out_valid_r <= 1;
                                    fb_out_data_r  <= route_payload[fb_pos[7:0]];
                                    fb_crc         <= crc16_next(fb_crc, route_payload[fb_pos[7:0]]);
                                    if (fb_pos == fb_len - 1) begin
                                        fb_state <= FB_CRC;
                                        fb_pos   <= 0;
                                    end else
                                        fb_pos <= fb_pos + 1;
                                end
                            end

                            FB_CRC: begin
                                if (fb_out_ready || !fb_out_valid_r) begin
                                    fb_out_valid_r <= 1;
                                    if (fb_pos == 0) begin
                                        fb_out_data_r <= fb_crc[15:8];
                                        fb_pos        <= 1;
                                    end else begin
                                        fb_out_data_r <= fb_crc[7:0];
                                        fb_out_eop_r  <= 1;
                                        fb_state      <= FB_IDLE;
                                        fb_active     <= 0;
                                        route_dispatches <= route_dispatches + 1;
                                    end
                                end
                            end

                            default: fb_state <= FB_IDLE;
                        endcase

                        if (spine_extract_valid && spine_extract_eop) begin
                            route_dispatches <= route_dispatches + 1;
                        end

                        pnm_rdata <= 32'h0;
                        if (sel_pnm && cpu_valid && !cpu_we) begin
                            case (pnm_addr)
                                8'h14: pnm_rdata <= {30'h0, 1'b0, pnm_busy};
                                8'h18: pnm_rdata <= {24'h0, spine_extract_data};
                                8'h1C: pnm_rdata <= route_errors;
                                8'h20: pnm_rdata <= route_dispatches;
                                default: ;
                            endcase
                        end
                    end
                end
        end

        if (ROLE == ROLE_SBC) begin : g_sbc
                // =========================================================================
                // Bus interconnect
                // =========================================================================
                wire [31:0] cpu_addr;
                wire [31:0] cpu_wdata;
                wire [31:0] cpu_rdata;
                wire        cpu_we;
                wire [3:0]  cpu_be;
                wire        cpu_valid;
                wire        cpu_ready;
                wire        cpu_error;

                reg [31:0] rom_rdata;
                reg [31:0] dram_rdata;
                reg        dram_ready;
                wire [31:0] uart_rdata;
                wire [31:0] clint_rdata;
                reg  [31:0] pnm_rdata;
                reg  [31:0] sram_rdata;
                wire [31:0] pcie_rdata;
                wire        pcie_ready;
                wire [31:0] nvme_rdata;
                wire        nvme_ready;
                wire [31:0] cpu_fetch_addr;

                wire sel_rom   = (cpu_fetch_addr[31:16] == 16'h0000);
                wire sel_uart  = (cpu_addr[31:8]  == 24'h1000_00);
                wire sel_clint = (cpu_addr[31:16] == 16'h2000);
                wire sel_sram  = (cpu_addr[31:28] == 4'h4);             // 0x4000_0000..0x4FFF_FFFF
                wire sel_dram  = (cpu_addr[31:30] == 2'b10);            // 0x8000_0000..0xBFFF_FFFF
                wire sel_pcie  = (cpu_addr[31:28] == 4'hC);             // 0xC000_0000..0xCFFF_FFFF
                wire sel_nvme  = (cpu_addr[31:28] == 4'hD);             // 0xD000_0000..0xDFFF_FFFF
                wire sel_pnm   = (cpu_addr[31:8]  == 24'hF000_00);

                assign cpu_error = 1'b0;

                reg [31:0] mux_rdata;
                always @(*) begin
                    mux_rdata = 32'h0;
                    if (sel_rom)        mux_rdata = rom_rdata;
                    else if (sel_uart)  mux_rdata = uart_rdata;
                    else if (sel_clint) mux_rdata = clint_rdata;
                    else if (sel_sram)  mux_rdata = sram_rdata;
                    else if (sel_dram)  mux_rdata = dram_rdata;
                    else if (sel_pcie)  mux_rdata = pcie_rdata;
                    else if (sel_nvme)  mux_rdata = nvme_rdata;
                    else if (sel_pnm)   mux_rdata = pnm_rdata;
                end

                assign cpu_rdata = mux_rdata;

                // Every access is acknowledged except the ones whose model can
                // stall; an unmapped read returns zero and an unmapped write
                // is dropped (a JAL/JALR link store writes to sp-4, and a boot
                // ROM that never sets sp would otherwise stall the core).
                assign cpu_ready = (sel_dram && !dram_ready) ? 1'b0 :
                                   (sel_pcie && !pcie_ready && cpu_we) ? 1'b0 :
                                   (sel_nvme && !nvme_ready) ? 1'b0 : 1'b1;

                // =========================================================================
                // CPU Core
                // =========================================================================
                rv32_core #(
                    .RESET_ADDR(32'h0000_0000),
                    .NMINT(16)
                ) u_cpu (
                    .clk       (clk),
                    .rst_n     (rst_n),
                    .bus_addr  (cpu_addr),
                    .bus_wdata (cpu_wdata),
                    .bus_rdata (cpu_rdata),
                    .bus_we    (cpu_we),
                    .bus_be    (cpu_be),
                    .bus_valid (cpu_valid),
                    .bus_ready (cpu_ready),
                    .bus_error (cpu_error),
                    .irq       (ext_irq),
                    .fetch_addr(cpu_fetch_addr)
                );

                // =========================================================================
                // Boot ROM (64KB)
                // =========================================================================
                reg [31:0] rom [0:16383];
                always @(*) rom_rdata = rom[cpu_fetch_addr[15:2]];

                // =========================================================================
                // On-chip SRAM (configurable: 500KB..32MB depending on board tier)
                //
                // Single-cycle combinational read, registered write. The von Neumann
                // constraint requires instructions to execute from fast local memory;
                // DRAM is too slow for per-cycle instruction fetch.
                //   - 500KB (128K words): MCU-class desk-side, bare-metal dispatch loop
                //   - 1-4MB: trimmed Linux tinyconfig or seL4 image
                //   - 16MB: full Linux + CPython userland
                //   - 32MB: headroom for complex data workflows
                //
                // The address window at 0x4000_0000 is 256MB; unused upper addresses
                // alias back via the (SRAM_WORDS-1) mask.
                // =========================================================================
                reg [31:0] sram_mem [0:SRAM_WORDS-1];

                always @(*) sram_rdata = sram_mem[cpu_addr[25:2] & (SRAM_WORDS-1)];

                always @(posedge clk) begin
                    if (sel_sram && cpu_valid && cpu_we) begin
                        if (cpu_be[0]) sram_mem[cpu_addr[25:2] & (SRAM_WORDS-1)][7:0]   <= cpu_wdata[7:0];
                        if (cpu_be[1]) sram_mem[cpu_addr[25:2] & (SRAM_WORDS-1)][15:8]  <= cpu_wdata[15:8];
                        if (cpu_be[2]) sram_mem[cpu_addr[25:2] & (SRAM_WORDS-1)][23:16] <= cpu_wdata[23:16];
                        if (cpu_be[3]) sram_mem[cpu_addr[25:2] & (SRAM_WORDS-1)][31:24] <= cpu_wdata[31:24];
                    end
                end

                // =========================================================================
                // System DRAM (LPDDR5 stub — behavioral array with CAS latency)
                //
                // Address space: 0x8000_0000 .. 0xBFFF_FFFF (1GB window).
                // Simulated array: DRAM_WORDS x 32 bits. This is where the Linux/Redox
                // kernel, CPython interpreter, and userland packages reside at runtime.
                // A 512MB minimum allocation is expected for kernel (~32MB) + CPython
                // runtime (~50MB) + pip-installed site-packages (~100-400MB depending
                // on workload) + heap headroom.
                //
                // The multi-cycle latency models row activate + column access delay.
                // All loads/stores to this window stall the CPU bus until ready.
                // =========================================================================
                reg [31:0] dram_mem [0:DRAM_WORDS-1];

                reg [7:0]  dram_wait_cnt;
                reg        dram_pending_rd;
                reg        dram_pending_wr;
                reg [3:0]  dram_wr_be;
                reg [31:0] dram_wr_data;
                reg [31:0] dram_wr_addr;
                reg [31:0] dram_rd_addr;

                wire [31:0] dram_offset = {4'b0000, cpu_addr[29:2]};

                always @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin
                        dram_rdata      <= 32'h0;
                        dram_ready      <= 1'b0;
                        dram_wait_cnt   <= 8'h0;
                        dram_pending_rd <= 1'b0;
                        dram_pending_wr <= 1'b0;
                        dram_wr_be      <= 4'h0;
                        dram_wr_data    <= 32'h0;
                        dram_wr_addr    <= 32'h0;
                        dram_rd_addr    <= 32'h0;
                    end else begin
                        dram_ready <= 1'b0;

                        if (dram_pending_rd) begin
                            if (dram_wait_cnt >= DRAM_LATENCY - 1) begin
                                dram_rdata      <= (dram_rd_addr < DRAM_WORDS) ?
                                                   dram_mem[dram_rd_addr] : 32'h0;
                                dram_ready      <= 1'b1;
                                dram_pending_rd <= 1'b0;
                            end else
                                dram_wait_cnt <= dram_wait_cnt + 1;
                        end else if (dram_pending_wr) begin
                            if (dram_wait_cnt >= DRAM_LATENCY - 1) begin
                                if (dram_wr_addr < DRAM_WORDS) begin
                                    if (dram_wr_be[0]) dram_mem[dram_wr_addr][7:0]   <= dram_wr_data[7:0];
                                    if (dram_wr_be[1]) dram_mem[dram_wr_addr][15:8]  <= dram_wr_data[15:8];
                                    if (dram_wr_be[2]) dram_mem[dram_wr_addr][23:16] <= dram_wr_data[23:16];
                                    if (dram_wr_be[3]) dram_mem[dram_wr_addr][31:24] <= dram_wr_data[31:24];
                                end
                                dram_ready      <= 1'b1;
                                dram_pending_wr <= 1'b0;
                            end else
                                dram_wait_cnt <= dram_wait_cnt + 1;
                        end else if (sel_dram && cpu_valid && cpu_we && !dram_pending_rd && !dram_pending_wr) begin
                            dram_wr_be      <= cpu_be;
                            dram_wr_data    <= cpu_wdata;
                            dram_wr_addr    <= dram_offset;
                            dram_pending_wr <= 1'b1;
                            dram_wait_cnt   <= 8'h0;
                        end else if (sel_dram && cpu_valid && !cpu_we && !dram_pending_rd && !dram_pending_wr) begin
                            dram_rd_addr    <= dram_offset;
                            dram_pending_rd <= 1'b1;
                            dram_wait_cnt   <= 8'h0;
                        end
                    end
                end

                // =========================================================================
                // UART
                // =========================================================================
                wire        uart_irq;
                wire        uart_ready;
                uart #(
                    .CLK_FREQ(CLK_FREQ),
                    .BAUD_RATE(BAUD_RATE)
                ) u_uart (
                    .clk(clk), .rst_n(rst_n),
                    .addr(cpu_addr), .wdata(cpu_wdata), .rdata(uart_rdata),
                    .we(cpu_we), .valid(sel_uart && cpu_valid), .ready(uart_ready),
                    .uart_rx(uart_rx), .uart_tx(uart_tx), .irq(uart_irq)
                );

                // =========================================================================
                // CLINT
                // =========================================================================
                wire clint_mtip, clint_msip;
                clint #(
                    .CLK_FREQ(CLK_FREQ),
                    .TIMER_PERIOD(CLK_FREQ / 10)
                ) u_clint (
                    .clk(clk), .rst_n(rst_n),
                    .addr(cpu_addr), .wdata(cpu_wdata), .rdata(clint_rdata),
                    .we(cpu_we), .be(cpu_be),
                    .valid(sel_clint && cpu_valid), .ready(),
                    .msip(clint_msip), .mtip(clint_mtip)
                );

                // =========================================================================
                // PCIe Gen5 x16 PHY (host DMA endpoint)
                // =========================================================================
                wire pcie_irq;
                wire pcie_link_up;
                wire [3:0] pcie_ltssm;

                pcie_phy #(
                    .LANES(16),
                    .GEN(5),
                    .MAX_PAYLOAD_BYTES(512),
                    .CPL_FIFO_WORDS(256),
                    .STAGE_WORDS(128),
                    .LB_WORDS(4096),
                    .LOOPBACK(1)
                ) u_pcie (
                    .clk       (clk),
                    .rst_n     (rst_n),
                    .ctl_addr  (cpu_addr[7:0]),
                    .ctl_wdata (cpu_wdata),
                    .ctl_we    (cpu_we),
                    .ctl_valid (sel_pcie && cpu_valid),
                    .ctl_ready (pcie_ready),
                    .ctl_rdata (pcie_rdata),
                    .irq       (pcie_irq),
                    .link_up   (pcie_link_up),
                    .ltssm_state(pcie_ltssm)
                );

                // =========================================================================
                // NVMe Storage Controller
                // =========================================================================
                wire nvme_irq;

                nvme_ctrl #(
                    .MAX_QUEUE_DEPTH(64),
                    .BLOCK_SIZE(512),
                    .MAX_TRANSFER(65536),
                    .PAGE_SIZE(4096)
                ) u_nvme (
                    .clk            (clk),
                    .rst_n          (rst_n),
                    .s_axi_addr     (cpu_addr[7:2]),
                    .s_axi_wdata    (cpu_wdata),
                    .s_axi_rdata    (nvme_rdata),
                    .s_axi_we       (cpu_we),
                    .s_axi_valid    (sel_nvme && cpu_valid),
                    .s_axi_ready    (nvme_ready),
                    .m_axis_rd_data (),
                    .m_axis_rd_valid(),
                    .m_axis_rd_last (),
                    .m_axis_rd_ready(1'b1),
                    .s_axis_wr_data (32'h0),
                    .s_axis_wr_valid(1'b0),
                    .s_axis_wr_ready(),
                    .s_axis_wr_last (1'b0),
                    .irq            (nvme_irq)
                );

                // =========================================================================
                // Interrupt routing
                // =========================================================================
                wire [15:0] cpu_irq;
                assign cpu_irq[0]    = uart_irq;
                assign cpu_irq[1]    = clint_mtip;
                assign cpu_irq[2]    = clint_msip;
                assign cpu_irq[3]    = spine_extract_valid;
                assign cpu_irq[4]    = pcie_irq;
                assign cpu_irq[5]    = nvme_irq;
                assign cpu_irq[15:6] = ext_irq[15:6];

                // =========================================================================
                // PNM Router Engine (same flit builder wire format)
                // =========================================================================
                localparam CTRL_COMPUTE = 8'h80;
                localparam VC_DESCENT   = 2'b10;

                reg [7:0]  route_layer;
                reg [7:0]  route_module;
                reg [15:0] route_len;
                reg [7:0]  route_payload [0:255];
                reg [7:0]  route_wpos;
                reg [31:0] route_errors;
                reg [31:0] route_dispatches;
                reg [31:0] route_weight_flits;
                reg        boot_done_r;
                assign boot_done = boot_done_r;

                localparam FB_IDLE    = 3'd0;
                localparam FB_HDR     = 3'd1;
                localparam FB_PAYLOAD = 3'd2;
                localparam FB_CRC     = 3'd3;

                reg [2:0]  fb_state;
                reg [7:0]  fb_layer_r;
                reg [7:0]  fb_module_r;
                reg [7:0]  fb_ctrl;
                reg [15:0] fb_len;
                reg [15:0] fb_pos;
                reg [15:0] fb_crc;
                reg        fb_active;
                reg [7:0]  fb_out_data_r;
                reg        fb_out_valid_r;
                reg        fb_out_sop_r;
                reg        fb_out_eop_r;

                wire fb_out_ready = spine_inject_ready;
                wire pnm_busy = fb_active;

                assign spine_inject_data  = fb_out_data_r;
                assign spine_inject_valid = fb_out_valid_r;
                assign spine_inject_sop   = fb_out_sop_r;
                assign spine_inject_eop   = fb_out_eop_r;
                assign spine_inject_vc    = VC_DESCENT;

                wire [7:0] pnm_addr = cpu_addr[7:0];

                always @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin
                        route_layer        <= 8'h0;
                        route_module       <= 8'h0;
                        route_len          <= 16'h0;
                        route_wpos         <= 8'h0;
                        route_errors       <= 32'h0;
                        route_dispatches   <= 32'h0;
                        route_weight_flits <= 32'h0;
                        fb_state           <= FB_IDLE;
                        fb_layer_r         <= 8'h0;
                        fb_module_r        <= 8'h0;
                        fb_ctrl            <= 8'h0;
                        fb_len             <= 16'h0;
                        fb_pos             <= 16'h0;
                        fb_crc             <= 16'hFFFF;
                        fb_active          <= 1'b0;
                        fb_out_data_r      <= 8'h0;
                        fb_out_valid_r     <= 1'b0;
                        fb_out_sop_r       <= 1'b0;
                        fb_out_eop_r       <= 1'b0;
                        pnm_rdata          <= 32'h0;
                        boot_done_r        <= 1'b0;
                    end else begin
                        fb_out_valid_r <= 1'b0;
                        fb_out_sop_r   <= 1'b0;
                        fb_out_eop_r   <= 1'b0;

                        if (sel_pnm && cpu_valid && cpu_we) begin
                            case (pnm_addr)
                                8'h04: route_layer  <= cpu_wdata[7:0];
                                8'h08: route_module <= cpu_wdata[7:0];
                                8'h0C: route_len    <= cpu_wdata[15:0];
                                8'h10: begin
                                    if (route_wpos != 8'hFF) begin  // prevent buffer overflow
                                        route_payload[route_wpos] <= cpu_wdata[7:0];
                                        route_wpos <= route_wpos + 1;
                                    end
                                end
                                8'h00: begin
                                    if (cpu_wdata[2]) boot_done_r <= 1'b1;
                                    if (!pnm_busy && cpu_wdata[0]) begin
                                        fb_layer_r  <= route_layer;
                                        fb_module_r <= route_module;
                                        fb_ctrl     <= CTRL_COMPUTE;
                                        fb_len      <= route_len;
                                        fb_state    <= FB_HDR;
                                        fb_pos      <= 16'h0;
                                        fb_crc      <= 16'hFFFF;
                                        fb_active   <= 1'b1;
                                        route_wpos  <= 8'h0;
                                    end
                                end
                                default: ;
                            endcase
                        end

                        case (fb_state)
                            FB_IDLE: ;

                            FB_HDR: begin
                                if (fb_out_ready || !fb_out_valid_r) begin
                                    fb_out_valid_r <= 1;
                                    case (fb_pos)
                                        0: begin fb_out_data_r <= fb_layer_r;  fb_out_sop_r <= 1; end
                                        1: begin fb_out_data_r <= fb_module_r; end
                                        2: begin fb_out_data_r <= fb_ctrl;     end
                                        3: begin fb_out_data_r <= fb_len[7:0]; end
                                        4: begin fb_out_data_r <= fb_len[15:8];end
                                    endcase
                                    if (fb_pos >= 1 && fb_pos <= 4) begin
                                        if (fb_pos == 1)      fb_crc <= crc16_next(16'hFFFF, fb_module_r);
                                        else if (fb_pos == 2) fb_crc <= crc16_next(fb_crc, fb_ctrl);
                                        else if (fb_pos == 3) fb_crc <= crc16_next(fb_crc, fb_len[7:0]);
                                        else                  fb_crc <= crc16_next(fb_crc, fb_len[15:8]);
                                    end
                                    if (fb_pos == 4) begin
                                        fb_state <= (fb_len == 0) ? FB_CRC : FB_PAYLOAD;
                                        fb_pos   <= 0;
                                    end else
                                        fb_pos <= fb_pos + 1;
                                end
                            end

                            FB_PAYLOAD: begin
                                if (fb_out_ready || !fb_out_valid_r) begin
                                    fb_out_valid_r <= 1;
                                    fb_out_data_r  <= route_payload[fb_pos[7:0]];
                                    fb_crc         <= crc16_next(fb_crc, route_payload[fb_pos[7:0]]);
                                    if (fb_pos == fb_len - 1) begin
                                        fb_state <= FB_CRC;
                                        fb_pos   <= 0;
                                    end else
                                        fb_pos <= fb_pos + 1;
                                end
                            end

                            FB_CRC: begin
                                if (fb_out_ready || !fb_out_valid_r) begin
                                    fb_out_valid_r <= 1;
                                    if (fb_pos == 0) begin
                                        fb_out_data_r <= fb_crc[15:8];
                                        fb_pos        <= 1;
                                    end else begin
                                        fb_out_data_r <= fb_crc[7:0];
                                        fb_out_eop_r  <= 1;
                                        fb_state      <= FB_IDLE;
                                        fb_active     <= 0;
                                        route_weight_flits <= route_weight_flits + 1;
                                    end
                                end
                            end

                            default: fb_state <= FB_IDLE;
                        endcase

                        if (spine_extract_valid && spine_extract_eop)
                            route_dispatches <= route_dispatches + 1;

                        pnm_rdata <= 32'h0;
                        if (sel_pnm && cpu_valid && !cpu_we) begin
                            case (pnm_addr)
                                8'h14: pnm_rdata <= {30'h0, 1'b0, pnm_busy};
                                8'h18: pnm_rdata <= {24'h0, spine_extract_data};
                                8'h1C: pnm_rdata <= route_errors;
                                8'h20: pnm_rdata <= route_dispatches;
                                8'h24: pnm_rdata <= route_weight_flits;
                                default: ;
                            endcase
                        end
                    end
                end
        end

        if (ROLE == ROLE_SBC_MOE) begin : g_sbc_moe
                // =========================================================================
                // Bus interconnect
                // =========================================================================
                wire [31:0] cpu_addr;
                wire [31:0] cpu_wdata;
                wire [31:0] cpu_rdata;
                wire        cpu_we;
                wire [3:0]  cpu_be;
                wire        cpu_valid;
                wire        cpu_ready;
                wire        cpu_error;

                reg  [31:0] rom_rdata;
                reg  [31:0] dram_rdata;
                reg         dram_ready;
                wire [31:0] uart_rdata;
                wire [31:0] clint_rdata;
                reg  [31:0] gating_rdata;
                reg  [31:0] pcie_rdata;
                reg  [31:0] pnm_rdata;
                wire [31:0] cpu_fetch_addr;

                wire sel_rom    = (cpu_fetch_addr[31:16] == 16'h0000);
                wire sel_uart   = (cpu_addr[31:8]  == 24'h1000_00);
                wire sel_clint  = (cpu_addr[31:16] == 16'h2000);
                wire sel_gating = (cpu_addr[31:16] == 16'h4000);       // 0x4000_0000
                wire sel_dram   = (cpu_addr[31:29] == 3'b100);          // 0x8000_0000..0x9FFF_FFFF
                wire sel_pcie   = (cpu_addr[31:8]  == 24'hC000_00);     // 0xC000_0000
                wire sel_pnm    = (cpu_addr[31:8]  == 24'hF000_00);

                assign cpu_error = 1'b0;

                reg [31:0] mux_rdata;
                always @(*) begin
                    mux_rdata = 32'h0;
                    if (sel_rom)       mux_rdata = rom_rdata;
                    else if (sel_uart) mux_rdata = uart_rdata;
                    else if (sel_clint) mux_rdata = clint_rdata;
                    else if (sel_gating) mux_rdata = gating_rdata;
                    else if (sel_dram)  mux_rdata = dram_rdata;
                    else if (sel_pcie)  mux_rdata = pcie_rdata;
                    else if (sel_pnm)   mux_rdata = pnm_rdata;
                end

                assign cpu_rdata = mux_rdata;

                // DRAM has multi-cycle latency; every other access is
                // acknowledged (an unmapped read returns zero, an unmapped
                // write is dropped).
                assign cpu_ready = (sel_dram && !dram_ready) ? 1'b0 : 1'b1;

                // =========================================================================
                // CPU Core (RV32IMA — production upgrades to RV32IMAFC)
                // =========================================================================
                rv32_core #(
                    .RESET_ADDR(32'h0000_0000),
                    .NMINT(16)
                ) u_cpu (
                    .clk       (clk),
                    .rst_n     (rst_n),
                    .bus_addr  (cpu_addr),
                    .bus_wdata (cpu_wdata),
                    .bus_rdata (cpu_rdata),
                    .bus_we    (cpu_we),
                    .bus_be    (cpu_be),
                    .bus_valid (cpu_valid),
                    .bus_ready (cpu_ready),
                    .bus_error (cpu_error),
                    .irq       (ext_irq),
                    .fetch_addr(cpu_fetch_addr)
                );

                // =========================================================================
                // Boot ROM (64KB)
                // =========================================================================
                reg [31:0] rom [0:16383];
                always @(*) rom_rdata = rom[cpu_fetch_addr[15:2]];

                // =========================================================================
                // System DRAM (LPDDR5 stub — behavioral array with CAS latency)
                //
                // Address space: 0x8000_0000 .. 0x9FFF_FFFF (512MB window).
                // Simulated array: DRAM_WORDS x 32 bits. Production replaces this
                // block with a hard LPDDR5 controller driving external DRAM chips.
                // The CAS latency models the row activate + column read delay.
                // =========================================================================
                reg [31:0] dram_mem [0:DRAM_WORDS-1];

                reg [7:0]  dram_wait_cnt;
                reg        dram_pending_rd;
                reg        dram_pending_wr;
                reg [3:0]  dram_wr_be;
                reg [31:0] dram_wr_data;
                reg [31:0] dram_wr_addr;
                reg [31:0] dram_rd_addr;

                wire [31:0] dram_offset = {2'b00, cpu_addr[28:2]};

                always @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin
                        dram_rdata      <= 32'h0;
                        dram_ready      <= 1'b0;
                        dram_wait_cnt   <= 8'h0;
                        dram_pending_rd <= 1'b0;
                        dram_pending_wr <= 1'b0;
                        dram_wr_be      <= 4'h0;
                        dram_wr_data    <= 32'h0;
                        dram_wr_addr    <= 32'h0;
                        dram_rd_addr    <= 32'h0;
                    end else begin
                        dram_ready <= 1'b0;

                        if (dram_pending_rd) begin
                            if (dram_wait_cnt >= DRAM_LATENCY - 1) begin
                                dram_rdata      <= (dram_rd_addr < DRAM_WORDS) ?
                                                   dram_mem[dram_rd_addr] : 32'h0;
                                dram_ready      <= 1'b1;
                                dram_pending_rd <= 1'b0;
                            end else
                                dram_wait_cnt <= dram_wait_cnt + 1;
                        end else if (dram_pending_wr) begin
                            if (dram_wait_cnt >= DRAM_LATENCY - 1) begin
                                if (dram_wr_addr < DRAM_WORDS) begin
                                    if (dram_wr_be[0]) dram_mem[dram_wr_addr][7:0]   <= dram_wr_data[7:0];
                                    if (dram_wr_be[1]) dram_mem[dram_wr_addr][15:8]  <= dram_wr_data[15:8];
                                    if (dram_wr_be[2]) dram_mem[dram_wr_addr][23:16] <= dram_wr_data[23:16];
                                    if (dram_wr_be[3]) dram_mem[dram_wr_addr][31:24] <= dram_wr_data[31:24];
                                end
                                dram_ready      <= 1'b1;
                                dram_pending_wr <= 1'b0;
                            end else
                                dram_wait_cnt <= dram_wait_cnt + 1;
                        end else if (sel_dram && cpu_valid && cpu_we && !dram_pending_rd && !dram_pending_wr) begin
                            dram_wr_be   <= cpu_be;
                            dram_wr_data <= cpu_wdata;
                            dram_wr_addr <= dram_offset;
                            dram_pending_wr <= 1'b1;
                            dram_wait_cnt   <= 8'h0;
                        end else if (sel_dram && cpu_valid && !cpu_we && !dram_pending_rd && !dram_pending_wr) begin
                            dram_rd_addr    <= dram_offset;
                            dram_pending_rd <= 1'b1;
                            dram_wait_cnt   <= 8'h0;
                        end
                    end
                end

                // =========================================================================
                // MoE Gating Weight SRAM (64KB = 32K BF16 entries)
                // =========================================================================
                reg [15:0] gating_sram [0:GATING_ENTRIES-1];

                always @(*) begin
                    if (sel_gating)
                        gating_rdata = {gating_sram[{cpu_addr[16:1], 1'b1}],
                                        gating_sram[{cpu_addr[16:1], 1'b0}]};
                    else
                        gating_rdata = 32'h0;
                end

                always @(posedge clk) begin
                    if (sel_gating && cpu_valid && cpu_we) begin
                        if (cpu_be[0]) gating_sram[{cpu_addr[16:1], 1'b0}][7:0]  <= cpu_wdata[7:0];
                        if (cpu_be[1]) gating_sram[{cpu_addr[16:1], 1'b0}][15:8] <= cpu_wdata[15:8];
                        if (cpu_be[2]) gating_sram[{cpu_addr[16:1], 1'b1}][7:0]  <= cpu_wdata[23:16];
                        if (cpu_be[3]) gating_sram[{cpu_addr[16:1], 1'b1}][15:8] <= cpu_wdata[31:24];
                    end
                end

                // =========================================================================
                // UART
                // =========================================================================
                wire        uart_irq;
                wire        uart_ready;
                uart #(
                    .CLK_FREQ(CLK_FREQ),
                    .BAUD_RATE(BAUD_RATE)
                ) u_uart (
                    .clk(clk), .rst_n(rst_n),
                    .addr(cpu_addr), .wdata(cpu_wdata), .rdata(uart_rdata),
                    .we(cpu_we), .valid(sel_uart && cpu_valid), .ready(uart_ready),
                    .uart_rx(uart_rx), .uart_tx(uart_tx), .irq(uart_irq)
                );

                // =========================================================================
                // CLINT
                // =========================================================================
                wire clint_mtip, clint_msip;
                clint #(
                    .CLK_FREQ(CLK_FREQ),
                    .TIMER_PERIOD(CLK_FREQ / 10)
                ) u_clint (
                    .clk(clk), .rst_n(rst_n),
                    .addr(cpu_addr), .wdata(cpu_wdata), .rdata(clint_rdata),
                    .we(cpu_we), .be(cpu_be),
                    .valid(sel_clint && cpu_valid), .ready(),
                    .msip(clint_msip), .mtip(clint_mtip)
                );

                // IRQ wiring
                wire [15:0] cpu_irq;
                assign cpu_irq[0]  = uart_irq;
                assign cpu_irq[1]  = clint_mtip;
                assign cpu_irq[2]  = clint_msip;
                assign cpu_irq[3]  = spine_extract_valid;
                assign cpu_irq[4]  = pcie_out_valid;
                assign cpu_irq[15:5] = ext_irq[15:5];

                // =========================================================================
                // MoE Gating Unit (computes top-K from hidden state)
                // =========================================================================
                wire        mg_start;
                wire        mg_done;
                wire [9:0]  mg_hidden_addr;
                wire [15:0] mg_hidden_data;
                wire        mg_weight_load;
                wire [9:0]  mg_weight_addr;
                wire [15:0] mg_weight_data;
                wire [7:0]  mg_current_layer;
                wire [TOP_K*8-1:0]  mg_expert_idx;
                wire [TOP_K*16-1:0] mg_expert_logit;
                wire [TOP_K*8-1:0]  mg_expert_layer;
                wire [TOP_K*8-1:0]  mg_expert_module;

                // Hidden state buffer: firmware writes token's hidden vector here
                reg [15:0] hidden_buf [0:HIDDEN_SIZE-1];

                assign mg_hidden_data = (mg_hidden_addr < HIDDEN_SIZE) ?
                                        hidden_buf[mg_hidden_addr] : 16'h0;

                // Weight data comes from the gating SRAM
                assign mg_weight_data = (mg_weight_addr < GATING_ENTRIES) ?
                                        gating_sram[mg_weight_addr] : 16'h0;

                // Control registers (CPU-programmed via PNM extension)
                reg        mg_trigger;      // CPU writes PNM_GATING_START
                reg        mg_active;
                reg [7:0]  mg_layer_reg;

                assign mg_start = mg_trigger && !mg_active;
                assign mg_current_layer = mg_layer_reg;

                moe_gating #(
                    .NUM_EXPERTS(MAX_EXPERTS),
                    .HIDDEN_DIM(64),          // gating projection dim (not full hidden)
                    .TOP_K(TOP_K),
                    .ADDR_BITS(10)
                ) u_moe_gating (
                    .clk(clk), .rst_n(rst_n),
                    .start(mg_start),
                    .done(mg_done),
                    .hidden_addr(mg_hidden_addr),
                    .hidden_data(mg_hidden_data),
                    .hidden_valid(1'b1),      // hidden_buf preloaded by firmware: free-run load
                    .weight_load(1'b0),       // weights loaded via CPU writes to SRAM
                    .weight_addr(mg_weight_addr),
                    .weight_data(mg_weight_data),
                    .current_layer(mg_current_layer),
                    .moe_layer_in(8'h0),
                    .moe_module_in(8'h0),
                    .expert_idx_packed(mg_expert_idx),
                    .expert_logit_packed(mg_expert_logit),
                    .expert_layer_packed(mg_expert_layer),
                    .expert_module_packed(mg_expert_module)
                );

                // When gating completes, latch results into CPU-readable registers
                reg [TOP_K*8-1:0]  gate_result_idx;
                reg [TOP_K*16-1:0] gate_result_logit;
                reg [TOP_K*8-1:0]  gate_result_layer;
                reg [TOP_K*8-1:0]  gate_result_module;

                always @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin
                        mg_trigger <= 1'b0;
                        mg_active  <= 1'b0;
                        mg_layer_reg <= 8'h0;
                        gate_result_idx    <= {(TOP_K*8){1'b0}};
                        gate_result_logit  <= {(TOP_K*16){1'b0}};
                        gate_result_layer  <= {(TOP_K*8){1'b0}};
                        gate_result_module <= {(TOP_K*8){1'b0}};
                    end else begin
                        if (mg_start) mg_active <= 1'b1;
                        if (mg_done) begin
                            mg_active           <= 1'b0;
                            mg_trigger          <= 1'b0;
                            gate_result_idx     <= mg_expert_idx;
                            gate_result_logit   <= mg_expert_logit;
                            gate_result_layer   <= mg_expert_layer;
                            gate_result_module  <= mg_expert_module;
                        end
                    end
                end

                // =========================================================================
                // PCIe Gen5 Endpoint Register Stub
                //
                // Production silicon integrates a Gen5 PHY + DMA controller. This stub
                // provides the register interface so firmware can be developed before
                // the physical layer exists. Writes to PCIE_TX push bytes toward the
                // host; reads from PCIE_RX pull bytes from the host.
                // =========================================================================
                reg [7:0]  pcie_tx_fifo [0:63];
                reg [7:0]  pcie_rx_fifo [0:63];
                reg [5:0]  pcie_tx_wptr, pcie_tx_rptr;
                reg [5:0]  pcie_rx_wptr, pcie_rx_rptr;
                reg [31:0] pcie_status;

                wire [7:0] pcie_addr = cpu_addr[7:0];
                wire pcie_tx_full  = ({~pcie_tx_wptr[5], pcie_tx_wptr[4:0]} == {pcie_tx_rptr[5], pcie_tx_rptr[4:0]});
                wire pcie_rx_empty = (pcie_rx_wptr == pcie_rx_rptr);

                assign pcie_in_ready  = !pcie_rx_empty || pcie_in_valid;
                assign pcie_out_data  = pcie_tx_fifo[pcie_tx_rptr];
                assign pcie_out_valid = (pcie_tx_rptr != pcie_tx_wptr);
                assign pcie_out_sop   = (pcie_tx_rptr == 6'd0);
                assign pcie_out_eop   = (pcie_tx_rptr + 6'd1 == pcie_tx_wptr);

                always @(*) begin
                    pcie_rdata = 32'h0;
                    case (pcie_addr)
                        8'h00: pcie_rdata = {24'h0, pcie_status};
                        8'h04: pcie_rdata = {24'h0,
                                             pcie_tx_full, ~pcie_rx_empty,
                                             5'h0, pcie_rx_fifo[pcie_rx_rptr]};
                        default: ;
                    endcase
                end

                always @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin
                        pcie_tx_wptr <= 6'd0; pcie_tx_rptr <= 6'd0;
                        pcie_rx_wptr <= 6'd0; pcie_rx_rptr <= 6'd0;
                        pcie_status  <= 32'h0;
                    end else begin
                        if (sel_pcie && cpu_valid && cpu_we) begin
                            case (pcie_addr)
                                8'h08: begin  // PCIE_TX: write byte to TX FIFO
                                    if (!pcie_tx_full) begin
                                        pcie_tx_fifo[pcie_tx_wptr] <= cpu_wdata[7:0];
                                        pcie_tx_wptr <= pcie_tx_wptr + 1;
                                    end
                                end
                                8'h0C: begin  // PCIE_RX_POP: advance RX read pointer
                                    if (!pcie_rx_empty)
                                        pcie_rx_rptr <= pcie_rx_rptr + 1;
                                end
                                8'h10: pcie_status <= cpu_wdata;
                                default: ;
                            endcase
                        end

                        // Host pushes data into RX FIFO
                        if (pcie_in_valid) begin
                            pcie_rx_fifo[pcie_rx_wptr] <= pcie_in_data;
                            pcie_rx_wptr <= pcie_rx_wptr + 1;
                        end

                        // TX consumed by host
                        if (pcie_out_valid && pcie_out_ready)
                            pcie_tx_rptr <= pcie_tx_rptr + 1;
                    end
                end

                // =========================================================================
                // PNM Router Engine (same flit builder as bmc_orchestrator_top)
                // Extended with MoE gating trigger/result registers.
                // =========================================================================
                localparam CTRL_COMPUTE = 8'h80;
                localparam VC_DESCENT   = 2'b10;

                reg [7:0]  route_layer;
                reg [7:0]  route_module;
                reg [15:0] route_len;
                reg [7:0]  route_payload [0:255];
                reg [7:0]  route_wpos;
                reg [31:0] route_errors;
                reg [31:0] route_dispatches;
                reg [31:0] route_weight_flits;
                reg        boot_done_r;
                assign boot_done = boot_done_r;

                localparam FB_IDLE    = 3'd0;
                localparam FB_HDR     = 3'd1;
                localparam FB_PAYLOAD = 3'd2;
                localparam FB_CRC     = 3'd3;

                reg [2:0]  fb_state;
                reg [7:0]  fb_layer_r;
                reg [7:0]  fb_module_r;
                reg [7:0]  fb_ctrl;
                reg [15:0] fb_len;
                reg [15:0] fb_pos;
                reg [15:0] fb_crc;
                reg        fb_active;
                reg [7:0]  fb_out_data_r;
                reg        fb_out_valid_r;
                reg        fb_out_sop_r;
                reg        fb_out_eop_r;

                wire fb_out_ready = spine_inject_ready;
                wire pnm_busy = fb_active;

                assign spine_inject_data  = fb_out_data_r;
                assign spine_inject_valid = fb_out_valid_r;
                assign spine_inject_sop   = fb_out_sop_r;
                assign spine_inject_eop   = fb_out_eop_r;
                assign spine_inject_vc    = VC_DESCENT;

                wire [7:0] pnm_addr = cpu_addr[7:0];

                // PNM extended register offsets (MoE gating)
                localparam PNMG_HIDDEN_BASE   = 8'h30;  // write hidden_buf[hpos]
                localparam PNMG_GATING_START  = 8'h34;  // write 1 to trigger
                localparam PNMG_RESULT_IDX0   = 8'h38;  // top-K expert indices (bytes 0-3)
                localparam PNMG_RESULT_IDX1   = 8'h3C;  // top-K expert indices (bytes 4-7)

                always @(posedge clk or negedge rst_n) begin
                    if (!rst_n) begin
                        route_layer        <= 8'h0;
                        route_module       <= 8'h0;
                        route_len          <= 16'h0;
                        route_wpos         <= 8'h0;
                        route_errors       <= 32'h0;
                        route_dispatches   <= 32'h0;
                        route_weight_flits <= 32'h0;
                        fb_state           <= FB_IDLE;
                        fb_layer_r         <= 8'h0;
                        fb_module_r        <= 8'h0;
                        fb_ctrl            <= 8'h0;
                        fb_len             <= 16'h0;
                        fb_pos             <= 16'h0;
                        fb_crc             <= 16'hFFFF;
                        fb_active          <= 1'b0;
                        fb_out_data_r      <= 8'h0;
                        fb_out_valid_r     <= 1'b0;
                        fb_out_sop_r       <= 1'b0;
                        fb_out_eop_r       <= 1'b0;
                        pnm_rdata          <= 32'h0;
                        boot_done_r        <= 1'b0;
                    end else begin
                        fb_out_valid_r <= 1'b0;
                        fb_out_sop_r   <= 1'b0;
                        fb_out_eop_r   <= 1'b0;

                        if (sel_pnm && cpu_valid && cpu_we) begin
                            case (pnm_addr)
                                8'h04: route_layer  <= cpu_wdata[7:0];
                                8'h08: route_module <= cpu_wdata[7:0];
                                8'h0C: route_len    <= cpu_wdata[15:0];
                                8'h10: begin
                                    route_payload[route_wpos] <= cpu_wdata[7:0];
                                    route_wpos <= route_wpos + 1;
                                end
                                8'h00: begin
                                    if (cpu_wdata[2]) boot_done_r <= 1'b1;
                                    if (!pnm_busy && cpu_wdata[0]) begin
                                        fb_layer_r  <= route_layer;
                                        fb_module_r <= route_module;
                                        fb_ctrl     <= CTRL_COMPUTE;
                                        fb_len      <= route_len;
                                        fb_state    <= FB_HDR;
                                        fb_pos      <= 16'h0;
                                        fb_crc      <= 16'hFFFF;
                                        fb_active   <= 1'b1;
                                        route_wpos  <= 8'h0;
                                    end
                                end
                                PNMG_HIDDEN_BASE: begin
                                    // Simplified: write one BF16 halfword per access
                                    hidden_buf[route_wpos] <= cpu_wdata[15:0];
                                    route_wpos <= route_wpos + 1;
                                end
                                PNMG_GATING_START: mg_trigger <= 1'b1;
                                default: ;
                            endcase
                        end

                        // Flit builder FSM
                        case (fb_state)
                            FB_IDLE: ;

                            FB_HDR: begin
                                if (fb_out_ready || !fb_out_valid_r) begin
                                    fb_out_valid_r <= 1;
                                    case (fb_pos)
                                        0: begin fb_out_data_r <= fb_layer_r;  fb_out_sop_r <= 1; end
                                        1: begin fb_out_data_r <= fb_module_r; end
                                        2: begin fb_out_data_r <= fb_ctrl;     end
                                        3: begin fb_out_data_r <= fb_len[7:0]; end
                                        4: begin fb_out_data_r <= fb_len[15:8];end
                                    endcase
                                    if (fb_pos >= 1 && fb_pos <= 4) begin
                                        if (fb_pos == 1)      fb_crc <= crc16_next(16'hFFFF, fb_module_r);
                                        else if (fb_pos == 2) fb_crc <= crc16_next(fb_crc, fb_ctrl);
                                        else if (fb_pos == 3) fb_crc <= crc16_next(fb_crc, fb_len[7:0]);
                                        else                  fb_crc <= crc16_next(fb_crc, fb_len[15:8]);
                                    end
                                    if (fb_pos == 4) begin
                                        fb_state <= (fb_len == 0) ? FB_CRC : FB_PAYLOAD;
                                        fb_pos   <= 0;
                                    end else
                                        fb_pos <= fb_pos + 1;
                                end
                            end

                            FB_PAYLOAD: begin
                                if (fb_out_ready || !fb_out_valid_r) begin
                                    fb_out_valid_r <= 1;
                                    fb_out_data_r  <= route_payload[fb_pos[7:0]];
                                    fb_crc         <= crc16_next(fb_crc, route_payload[fb_pos[7:0]]);
                                    if (fb_pos == fb_len - 1) begin
                                        fb_state <= FB_CRC;
                                        fb_pos   <= 0;
                                    end else
                                        fb_pos <= fb_pos + 1;
                                end
                            end

                            FB_CRC: begin
                                if (fb_out_ready || !fb_out_valid_r) begin
                                    fb_out_valid_r <= 1;
                                    if (fb_pos == 0) begin
                                        fb_out_data_r <= fb_crc[15:8];
                                        fb_pos        <= 1;
                                    end else begin
                                        fb_out_data_r <= fb_crc[7:0];
                                        fb_out_eop_r  <= 1;
                                        fb_state      <= FB_IDLE;
                                        fb_active     <= 0;
                                        route_weight_flits <= route_weight_flits + 1;
                                    end
                                end
                            end

                            default: fb_state <= FB_IDLE;
                        endcase

                        if (spine_extract_valid && spine_extract_eop)
                            route_dispatches <= route_dispatches + 1;

                        pnm_rdata <= 32'h0;
                        if (sel_pnm && cpu_valid && !cpu_we) begin
                            case (pnm_addr)
                                8'h14: pnm_rdata <= {30'h0, 1'b0, pnm_busy};
                                8'h18: pnm_rdata <= {24'h0, spine_extract_data};
                                8'h1C: pnm_rdata <= route_errors;
                                8'h20: pnm_rdata <= route_dispatches;
                                8'h24: pnm_rdata <= route_weight_flits;
                                PNMG_GATING_START: pnm_rdata <= {30'h0, mg_active, mg_done};
                                PNMG_RESULT_IDX0:  pnm_rdata <= gate_result_idx[TOP_K*8-1 -: 32];
                                PNMG_RESULT_IDX1:  pnm_rdata <= {{(32-TOP_K*8>0)?(32-TOP_K*8):1{1'b0}}, gate_result_idx};
                                default: ;
                            endcase
                        end
                    end
                end
        end

    endgenerate

endmodule
